WITH exploded AS (SELECT id, created_at, coupon_codes, k, v FROM carts LATERAL VIEW EXPLODE(attributes) x AS k, v), exploded_carts AS (SELECT id, k, v, tag FROM exploded LATERAL VIEW OUTER EXPLODE(coupon_codes) x AS tag), cleaned AS (SELECT *, TRIM(tag) AS clean_tag FROM exploded_carts WHERE tag = 'BUNDLE'), cleaned_carts AS (SELECT id, k, v, tag, clean_tag, CASE WHEN k IN ('utm_source', 'weight_kg') THEN 'Group A' ELSE 'Other' END AS k_group, COALESCE(tag, 'UNKNOWN') AS tag_filled FROM cleaned WHERE tag IS NOT NULL) SELECT k, v, tag, clean_tag, k_group, tag_filled FROM cleaned_carts
